def test_transpose(self):
    def fn(a, b):
        return (
            torch.t(a) + b,
            torch.transpose(b * 2, 0, 1) + 10,
        )

    self.common(fn, (torch.randn(8, 8), torch.randn(8, 8)))

def test_permute1(self):
    def fn(a):
        return (
            torch.permute(a + 1, [2, 1, 4, 0, 3]) + 2,
            torch.permute(a, [2, 1, 4, 0, 3]) + 2,
        )

    self.common(fn, (torch.randn(2, 2, 2, 2, 2),))

@torch._dynamo.config.patch(capture_scalar_outputs=True)
def test_permute_unbacked_slice(self):
    def eager(a, end_t):
        b = a + 1
        c = torch.permute(b, [0, 2, 1])
        end = end_t.item()
        return c[:, :end, :]

    compiled = torch.compile(eager, backend="inductor")
    a = torch.randn(4, 16, 8, device=self.device)
    end_t = torch.tensor([5])
    self.assertEqual(compiled(a, end_t), eager(a, end_t))

def test_expand(self):
    def fn(a):
        return (
            (a + 1).expand(3, 4, 2, 3, 2) + 2,
            a.expand(2, 1, 2, 3, 2) + 2,
        ), a.expand(2, -1, 5, -1)

    self.common(fn, (torch.randn(2, 1, 2),))

def test_squeeze1(self):
    def fn(a):
        return ((a + 1).squeeze() + 2, a.squeeze() + 2)

    self.common(fn, (torch.randn(1, 2, 1, 2, 2, 1, 1),))

def test_squeeze2(self):
    def fn(a):
        return ((a + 1).squeeze(-1).squeeze(2) + 2, a.squeeze(0) + 2)

    self.common(fn, (torch.randn(1, 2, 1, 2, 2, 2, 1),))

def test_squeeze_varargs(self):
    def fn(x):
        return x.squeeze(1, 2).clone()

    a = torch.randn(1024, 1, 1)
    self.common(fn, (a,))
